## **1️⃣ Create CV**

### **Endpoint:**

```
bashCopyEditPOST /api/cvs/createCv

 ```

### **Headers:**

```
jsonCopyEdit{
  "Authorization": "Bearer <your_access_token>",
  "Content-Type": "application/json"
}

 ```

### **Request Body:**

```
jsonCopyEdit{
  "name": "John Doe",
  "position": "Software Engineer",
  "contactInformation": "123-456-7890",
  "email": "johndoe@example.com",
  "address": "New York, USA",
  "skills": [
    {
      "title": "Programming",
      "skills": ["JavaScript", "TypeScript"]
    }
  ],
  "workExperience": [
    {
      "company": "Tech Corp",
      "position": "Frontend Developer",
      "startYear": "2020-01-01",
      "endYear": "2023-06-30",
      "location": "San Francisco, USA"
    }
  ]
}

 ```

### **Response Example:**

```
jsonCopyEdit{
  "status": "success",
  "message": "Cv created successfully",
  "data": {
    "_id": "cv_id_12345",
    "name": "John Doe",
    "position": "Software Engineer"
  }
}

 ```

### **🔹 React Example: Create CV**

```
tsxCopyEditimport React, { useState } from "react";
const CreateCV = () => {
  const [cvData, setCvData] = useState({
    name: "",
    position: "",
    contactInformation: "",
    email: "",
    address: "",
  });
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setCvData({ ...cvData, [e.target.name]: e.target.value });
  };
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await fetch("http://localhost:5000/api/cvs/createCv", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
        body: JSON.stringify(cvData),
      });
      const data = await response.json();
      console.log("CV Created:", data);
    } catch (error) {
      console.error("Error creating CV:", error);
    }
  };
  return (
    <form onSubmit={handleSubmit}>
      <input type="text" name="name" placeholder="Full Name" onChange={handleChange} />
      <input type="text" name="position" placeholder="Position" onChange={handleChange} />
      <button type="submit">Create CV</button>
    </form>
  );
};
export default CreateCV;

 ```

---

## **2️⃣ Get All My CVs**

### **Endpoint:**

```
bashCopyEditGET /api/cvs/getAllMyCvs

 ```

### **Headers:**

```
jsonCopyEdit{
  "Authorization": "Bearer <your_access_token>"
}

 ```

### **Response Example:**

```
jsonCopyEdit{
  "status": "success",
  "data": [
    {
      "_id": "cv_id_12345",
      "name": "John Doe",
      "position": "Software Engineer",
      "email": "johndoe@example.com",
      "workExperience": [
        {
          "company": "Tech Corp",
          "position": "Frontend Developer"
        }
      ]
    }
  ]
}

 ```

### **🔹 React Example: Fetch My CVs**

```
tsxCopyEditimport React, { useEffect, useState } from "react";
const MyCVs = () => {
  const [cvs, setCvs] = useState([]);
  useEffect(() => {
    const fetchCvs = async () => {
      try {
        const response = await fetch("http://localhost:5000/api/cvs/getAllMyCvs", {
          method: "GET",
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        });
        const data = await response.json();
        setCvs(data.data);
      } catch (error) {
        console.error("Error fetching CVs:", error);
      }
    };
    fetchCvs();
  }, []);
  return (
    <div>
      <h2>My CVs</h2>
      <ul>
        {cvs.map((cv) => (
          <li key={cv._id}>{cv.name} - {cv.position}</li>
        ))}
      </ul>
    </div>
  );
};
export default MyCVs;

 ```

